import{_ as a,c as e,o as i,a0 as o}from"./chunks/framework.DKRgXLPU.js";const l=JSON.parse('{"title":"Competition Preparation","description":"Prepare optimally for pétanque competitions. Learn the physical, mental, and tactical preparation that sets you up for peak performance.","frontmatter":{"title":"Competition Preparation","description":"Prepare optimally for pétanque competitions. Learn the physical, mental, and tactical preparation that sets you up for peak performance."},"headers":[],"relativePath":"es/blog/competition-prep.md","filePath":"es/blog/competition-prep.md"}');const n=a({name:"es/blog/competition-prep.md"},[["render",function(a,l,n,r,t,s){return i(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="preparacion-para-la-competicion" tabindex="-1">Preparación para la competición <a class="header-anchor" href="#preparacion-para-la-competicion" aria-label="Permalink to &quot;Preparación para la competición&quot;">​</a></h1><p>El partido no empieza cuando se lanza la primera bola, sino días antes. La preparación previa a la competición influye significativamente en el rendimiento. Los jugadores de élite no dejan la preparación al azar.</p><h2 id="el-cronograma-de-preparacion" tabindex="-1">El cronograma de preparación <a class="header-anchor" href="#el-cronograma-de-preparacion" aria-label="Permalink to &quot;El cronograma de preparación&quot;">​</a></h2><h3 id="una-semana-antes" tabindex="-1">Una semana antes <a class="header-anchor" href="#una-semana-antes" aria-label="Permalink to &quot;Una semana antes&quot;">​</a></h3><p><strong>Físico:</strong></p><ul><li>Mantener la intensidad normal del entrenamiento</li><li>Asegúrese de un descanso adecuado</li><li>Abordar cualquier problema físico menor</li></ul><p><strong>Mental:</strong></p><ul><li>Visualizar un desempeño exitoso</li><li>Revisar los objetivos de la competencia</li><li>Comience a centrar la atención</li></ul><p><strong>Táctico:</strong></p><ul><li>Investiga a los oponentes si es posible</li><li>Revisa tu plan de juego</li><li>Discutir la estrategia con los compañeros de equipo</li></ul><h3 id="dos-dias-antes" tabindex="-1">Dos días antes <a class="header-anchor" href="#dos-dias-antes" aria-label="Permalink to &quot;Dos días antes&quot;">​</a></h3><p><strong>Físico:</strong></p><ul><li>Reducir la intensidad del entrenamiento</li><li>Concéntrese en sentirse bien, no en mejorar</li><li>Priorizar el sueño</li></ul><p><strong>Mental:</strong></p><ul><li>Aumentar la práctica de visualización</li><li>Gestionar los nervios previos a la competición</li><li>Manténgase positivo y confiado</li></ul><p><strong>Logístico:</strong></p><ul><li>Preparar el equipo</li><li>Planificar el viaje y el tiempo</li><li>Manejar detalles administrativos</li></ul><h3 id="el-dia-anterior" tabindex="-1">El día anterior <a class="header-anchor" href="#el-dia-anterior" aria-label="Permalink to &quot;El día anterior&quot;">​</a></h3><p><strong>Físico:</strong></p><ul><li>Solo práctica ligera</li><li>Descanso y recuperación</li><li>Buena nutrición e hidratación</li></ul><p><strong>Mental:</strong></p><ul><li>Sesión de visualización final</li><li>Técnicas de relajación</li><li>Diálogo interno positivo</li></ul><p><strong>Práctico:</strong></p><ul><li>Confirmar toda la logística</li><li>Prepara lo que vas a vestir</li><li>Establecer alarmas y recordatorios</li></ul><h3 id="dia-de-la-competicion" tabindex="-1">Día de la competición <a class="header-anchor" href="#dia-de-la-competicion" aria-label="Permalink to &quot;Día de la competición&quot;">​</a></h3><p><strong>Mañana:</strong></p><ul><li>Despierta con tiempo adecuado</li><li>Coma alimentos familiares y probados</li><li>Comenzar la preparación mental</li></ul><p><strong>Antes del partido:</strong></p><ul><li>Llegar temprano</li><li>Familiarizarse con el terreno</li><li>Rutina completa de calentamiento</li><li>Alineación final del equipo</li></ul><h2 id="preparacion-fisica" tabindex="-1">Preparación física <a class="header-anchor" href="#preparacion-fisica" aria-label="Permalink to &quot;Preparación física&quot;">​</a></h2><h3 id="dormir" tabindex="-1">Dormir <a class="header-anchor" href="#dormir" aria-label="Permalink to &quot;Dormir&quot;">​</a></h3><p>El sueño es combustible para el rendimiento:</p><ul><li>Prioriza de 7 a 9 horas en los días previos</li><li>Mantener un horario de sueño constante</li><li>Evite el alcohol y las pantallas antes de acostarse.</li></ul><h3 id="nutricion" tabindex="-1">Nutrición <a class="header-anchor" href="#nutricion" aria-label="Permalink to &quot;Nutrición&quot;">​</a></h3><p>Impulsa tu rendimiento:</p><ul><li>Coma alimentos familiares (no experimentales)</li><li>Mantente hidratado</li><li>Evite las comidas pesadas cerca del juego.</li><li>Tenga bocadillos disponibles durante la competencia.</li></ul><h3 id="preparacion-fisica-1" tabindex="-1">Preparación física <a class="header-anchor" href="#preparacion-fisica-1" aria-label="Permalink to &quot;Preparación física&quot;">​</a></h3><p>Llegar listo para actuar:</p><ul><li>Abordar cualquier lesión o malestar.</li><li>Calentar adecuadamente</li><li>Manténgase relajado entre partidos</li></ul><h2 id="preparacion-mental" tabindex="-1">Preparación mental <a class="header-anchor" href="#preparacion-mental" aria-label="Permalink to &quot;Preparación mental&quot;">​</a></h2><h3 id="visualizacion" tabindex="-1">Visualización <a class="header-anchor" href="#visualizacion" aria-label="Permalink to &quot;Visualización&quot;">​</a></h3><p>Vea el éxito antes de que suceda:</p><ul><li>Visualiza escenarios específicos a los que podrías enfrentarte</li><li>Imagínate manejando bien la presión</li><li>Siente la confianza del buen desempeño</li></ul><h3 id="establecimiento-de-metas" tabindex="-1">Establecimiento de metas <a class="header-anchor" href="#establecimiento-de-metas" aria-label="Permalink to &quot;Establecimiento de metas&quot;">​</a></h3><p>Sepa cuál es su objetivo:</p><ul><li>Objetivos de resultados (lo que quieres lograr)</li><li>Objetivos del proceso (cómo jugarás)</li><li>Objetivos de enfoque (hacia dónde se dirige la atención)</li></ul><h3 id="fomento-de-la-confianza" tabindex="-1">Fomento de la confianza <a class="header-anchor" href="#fomento-de-la-confianza" aria-label="Permalink to &quot;Fomento de la confianza&quot;">​</a></h3><p>Participa en el concurso creyendo en ti mismo:</p><ul><li>Revisar los éxitos pasados</li><li>Afirma tu preparación</li><li>Centrarse en las fortalezas</li></ul><h3 id="manejo-de-la-ansiedad" tabindex="-1">Manejo de la ansiedad <a class="header-anchor" href="#manejo-de-la-ansiedad" aria-label="Permalink to &quot;Manejo de la ansiedad&quot;">​</a></h3><p>Canalizar los nervios de forma productiva:</p><ul><li>Reconozca la ansiedad como algo normal</li><li>Utilice técnicas de respiración</li><li>Replantee los nervios como emoción</li></ul><h2 id="preparacion-tactica" tabindex="-1">Preparación táctica <a class="header-anchor" href="#preparacion-tactica" aria-label="Permalink to &quot;Preparación táctica&quot;">​</a></h2><h3 id="conozca-su-juego" tabindex="-1">Conozca su juego <a class="header-anchor" href="#conozca-su-juego" aria-label="Permalink to &quot;Conozca su juego&quot;">​</a></h3><p>Tenga claro su enfoque:</p><ul><li>¿Cuál es el estilo de tu equipo?</li><li>¿Cuales son sus puntos fuertes a aprovechar?</li><li>¿Qué debilidades gestionar?</li></ul><h3 id="conozca-la-competencia" tabindex="-1">Conozca la competencia <a class="header-anchor" href="#conozca-la-competencia" aria-label="Permalink to &quot;Conozca la competencia&quot;">​</a></h3><p>Recopilar información útil:</p><ul><li>Tendencias de los oponentes</li><li>Características del terreno</li><li>Formato y reglas del concurso</li></ul><h3 id="tenga-un-plan" tabindex="-1">Tenga un plan <a class="header-anchor" href="#tenga-un-plan" aria-label="Permalink to &quot;Tenga un plan&quot;">​</a></h3><p>Entrar con intenciones claras:</p><ul><li>Estrategia de apertura</li><li>Ajustes para diferentes escenarios</li><li>Roles y responsabilidades</li></ul><h2 id="preparacion-del-equipo" tabindex="-1">Preparación del equipo <a class="header-anchor" href="#preparacion-del-equipo" aria-label="Permalink to &quot;Preparación del equipo&quot;">​</a></h2><h3 id="alineacion" tabindex="-1">Alineación <a class="header-anchor" href="#alineacion" aria-label="Permalink to &quot;Alineación&quot;">​</a></h3><p>Asegúrese de que todos estén en sintonía:</p><ul><li>Objetivos compartidos</li><li>Roles claros</li><li>Enfoque de comunicación acordado</li></ul><h3 id="sistemas-de-soporte" tabindex="-1">Sistemas de soporte <a class="header-anchor" href="#sistemas-de-soporte" aria-label="Permalink to &quot;Sistemas de soporte&quot;">​</a></h3><p>Establecer apoyo mutuo:</p><ul><li>¿Cómo se animarán unos a otros?</li><li>¿Cómo afrontarás los contratiempos?</li><li>¿Cómo se ve el soporte?</li></ul><h3 id="logistica" tabindex="-1">Logística <a class="header-anchor" href="#logistica" aria-label="Permalink to &quot;Logística&quot;">​</a></h3><p>Manejar asuntos prácticos:</p><ul><li>Arreglos de viaje</li><li>Horarios y lugares de reunión</li><li>Responsabilidades del equipo</li></ul><h2 id="la-rutina-de-calentamiento" tabindex="-1">La rutina de calentamiento <a class="header-anchor" href="#la-rutina-de-calentamiento" aria-label="Permalink to &quot;La rutina de calentamiento&quot;">​</a></h2><h3 id="calentamiento-fisico-15-20-minutos" tabindex="-1">Calentamiento físico (15-20 minutos) <a class="header-anchor" href="#calentamiento-fisico-15-20-minutos" aria-label="Permalink to &quot;Calentamiento físico (15-20 minutos)&quot;">​</a></h3><ol><li>Movimiento ligero (caminar, hacer círculos con los brazos)</li><li>Estiramiento dinámico</li><li>Lanzamiento gradual (distancia corta a larga)</li><li>Lanzamientos de máxima intensidad</li></ol><h3 id="calentamiento-mental-5-10-minutos" tabindex="-1">Calentamiento mental (5-10 minutos) <a class="header-anchor" href="#calentamiento-mental-5-10-minutos" aria-label="Permalink to &quot;Calentamiento mental (5-10 minutos)&quot;">​</a></h3><ol><li>Enfoque de transición hacia la competencia</li><li>Visualización breve</li><li>Diálogo interno positivo</li><li>Establecimiento de intenciones</li></ol><h3 id="familiarizacion-con-el-terreno" tabindex="-1">Familiarización con el terreno <a class="header-anchor" href="#familiarizacion-con-el-terreno" aria-label="Permalink to &quot;Familiarización con el terreno&quot;">​</a></h3><ol><li>Observar la superficie de juego</li><li>Tenga en cuenta cualquier irregularidad</li><li>Pruebe diferentes áreas si es posible</li><li>Discuta las observaciones con el equipo.</li></ol><h2 id="errores-comunes-de-preparacion" tabindex="-1">Errores comunes de preparación <a class="header-anchor" href="#errores-comunes-de-preparacion" aria-label="Permalink to &quot;Errores comunes de preparación&quot;">​</a></h2><h3 id="sobreentrenamiento" tabindex="-1">Sobreentrenamiento <a class="header-anchor" href="#sobreentrenamiento" aria-label="Permalink to &quot;Sobreentrenamiento&quot;">​</a></h3><p>Intentar mejorar en los últimos días conduce a la fatiga, no a ganancias.</p><h3 id="dormir-poco" tabindex="-1">Dormir poco <a class="header-anchor" href="#dormir-poco" aria-label="Permalink to &quot;Dormir poco&quot;">​</a></h3><p>Sacrificar el sueño a cambio de práctica adicional es contraproducente.</p><h3 id="nuevos-experimentos" tabindex="-1">Nuevos experimentos <a class="header-anchor" href="#nuevos-experimentos" aria-label="Permalink to &quot;Nuevos experimentos&quot;">​</a></h3><p>El día de competición no es para probar nuevas técnicas o equipos.</p><h3 id="ignorando-los-nervios" tabindex="-1">Ignorando los nervios <a class="header-anchor" href="#ignorando-los-nervios" aria-label="Permalink to &quot;Ignorando los nervios&quot;">​</a></h3><p>Fingir que no estás nervioso no ayuda. Reconócelo y contrólalo.</p><h3 id="mala-logistica" tabindex="-1">Mala logística <a class="header-anchor" href="#mala-logistica" aria-label="Permalink to &quot;Mala logística&quot;">​</a></h3><p>Apresurarse debido a una mala planificación crea estrés innecesario.</p><h2 id="la-noche-anterior" tabindex="-1">La noche anterior <a class="header-anchor" href="#la-noche-anterior" aria-label="Permalink to &quot;La noche anterior&quot;">​</a></h2><h3 id="hacer" tabindex="-1">Hacer: <a class="header-anchor" href="#hacer" aria-label="Permalink to &quot;Hacer:&quot;">​</a></h3><ul><li>Prepara todo lo que necesitas</li><li>Acuéstate a la hora habitual</li><li>Utilice técnicas de relajación si es necesario.</li><li>Confía en tu preparación</li></ul><h3 id="no" tabindex="-1">No: <a class="header-anchor" href="#no" aria-label="Permalink to &quot;No:&quot;">​</a></h3><ul><li>Quedarse despierto hasta tarde preocupándose</li><li>Analizar en exceso la estrategia</li><li>Consumir alcohol o comidas pesadas</li><li>Participar en actividades estresantes</li></ul><h2 id="manana-de-competicion" tabindex="-1">Mañana de competición <a class="header-anchor" href="#manana-de-competicion" aria-label="Permalink to &quot;Mañana de competición&quot;">​</a></h2><h3 id="la-rutina-importa" tabindex="-1">La rutina importa <a class="header-anchor" href="#la-rutina-importa" aria-label="Permalink to &quot;La rutina importa&quot;">​</a></h3><p>Apéguese a los patrones familiares:</p><ul><li>Despertar a la hora planificada</li><li>Coma alimentos probados</li><li>Sigue tu rutina matutina habitual</li><li>Salir con tiempo de sobra</li></ul><h3 id="estado-mental" tabindex="-1">Estado mental <a class="header-anchor" href="#estado-mental" aria-label="Permalink to &quot;Estado mental&quot;">​</a></h3><p>Cultiva la mentalidad correcta:</p><ul><li>Emocionado, no ansioso</li><li>Seguro, no arrogante</li><li>Concentrado, no tenso</li><li>Listo, no desesperado</li></ul><h2 id="llegada-al-lugar" tabindex="-1">Llegada al lugar <a class="header-anchor" href="#llegada-al-lugar" aria-label="Permalink to &quot;Llegada al lugar&quot;">​</a></h2><ol><li><strong>Instálate</strong>: Encuentra tu espacio, organiza el equipo</li><li><strong>Observar</strong>: Mira el terreno, anota las condiciones.</li><li><strong>Calentamiento</strong>: Completa tu rutina</li><li><strong>Conectar</strong>: Breve alineación del equipo</li><li><strong>Enfoque</strong>: Preparación mental final</li></ol><p>Te has preparado bien. Ahora confía y compite.</p><hr><p>| <em>Relacionado: <a href="/es/educacion/formacion/">Métodos de formación</a> | <a href="/es/educacion/fuerza-mental/manejo-de-la-presion">Manejo de la presión</a> | <a href="/es/educacion/fuerza-mental/rutina-pre-disparo">Rutina pre-disparo</a></em> |</p>',107)])])}]]);export{l as __pageData,n as default};
